const hostOf = (url: string) => {
  try {
    return new URL(url).hostname
  } catch {
    return url
  }
}

const pause = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

export default function Demo() {
  const links = useCollection<SavedLink>("action-palette-demo", seed)
  const [preview, setPreview] = useState<Preview>("live")
  const [selectedIds, setSelectedIds] = useState<string[]>([])

  const live = preview === "live"
  const status =
    preview === "loading" ? "loading" : preview === "error" ? "error" : links.status
  const items = live ? [...links.items].sort((a, b) => Number(b.pinned) - Number(a.pinned)) : []

  function getActions(link: SavedLink, selection: SavedLink[]): PaletteAction<SavedLink>[] {
    const many = selection.length > 1
    const allPinned = selection.every((item) => item.pinned)
    const open: PaletteAction<SavedLink> = {
      id: "open",
      title: "Open",
      section: "use",
      run: (item) => void window.open(item.url, "_blank", "noopener,noreferrer"),
    }
    return [
      ...(many ? [] : [open]),
      {
        id: "copy",
        title: many ? "Copy URLs" : "Copy URL",
        section: "use",
        pending: "Copying URL…",
        successMessage: many ? `${selection.length} URLs copied` : "URL copied",
        run: (item) => navigator.clipboard.writeText(item.url),
        runMany: (picked) => navigator.clipboard.writeText(picked.map((item) => item.url).join("\n")),
      },
      {
        id: "pin",
        title: (many ? allPinned : link.pinned) ? "Unpin" : "Pin",
        section: "organize",
        shortcut: "mod+shift+p",
        run: (item) => links.update(item.id, { pinned: !item.pinned }),
        runMany: async (picked) => {
          for (const item of picked) await links.update(item.id, { pinned: !allPinned })
        },
      },
      {
        id: "move",
        title: "Move to…",
        section: "organize",
        children: FOLDERS.map((folder) => ({
          id: `move-${folder}`,
          title: folder,
          successMessage: many ? `${selection.length} moved to ${folder}` : `Moved to ${folder}`,
          run: (item: SavedLink) => links.update(item.id, { folder }),
        })),
      },
      {
        id: "delete",
        title: many ? `Delete ${selection.length}` : "Delete",
        destructive: true,
        shortcut: "mod+backspace",
        pending: "Deleting…",
        successMessage: "Deleted",
        run: async (item) => {
          await pause(600)
          await links.remove(item.id)
        },
        runMany: async (picked) => {
          await pause(600)
          for (const item of picked) await links.remove(item.id)
          setSelectedIds([])
        },
      },
    ]
  }

  return (
    <div className="flex flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center gap-2">
        <span id="action-palette-preview-label" className="text-xs text-muted-foreground">
          Preview state
        </span>
        <ToggleGroup
          type="single"
          variant="outline"
          size="sm"
          value={preview}
          onValueChange={(value) => value && setPreview(value as Preview)}
          aria-labelledby="action-palette-preview-label"
        >
          {(["live", "empty", "loading", "error"] as const).map((value) => (
            <ToggleGroupItem key={value} value={value} aria-label={`Show ${value} state`}>
              {value}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      </div>

      <div className="h-[32rem] max-w-3xl">
        <ActionPalette
          items={items}
          status={status}
          error={preview === "error" ? new Error("Could not read saved links") : links.error}
          onRetry={() => setPreview("live")}
          getActions={getActions}
          selectedIds={live ? selectedIds : []}
          onSelectedIdsChange={setSelectedIds}
          getSubtitle={(link) => hostOf(link.url)}
          getMeta={(link) => link.kind}
          getSearchText={(link) => `${link.url} ${link.folder}`}
          getSection={(link) => (link.pinned ? "Pinned" : "Saved")}
          onCreate={
            live
              ? (title) =>
                  void links.add({
                    id: crypto.randomUUID(),
                    title,
                    url: `https://example.com/${encodeURIComponent(title.toLowerCase().replace(/\s+/g, "-"))}`,
                    kind: "Link",
                    pinned: false,
                    folder: "Reading",
                  })
              : undefined
          }
          placeholder="Search saved links…"
          footerLabel="Saved links"
          emptyState={{
            title: "No saved links yet",
            description: "Links you save show up here.",
          }}
        />
      </div>

      <p className="max-w-3xl text-xs text-muted-foreground">
        ↑ ↓ move · ↵ run the first action · ⌘K actions · ⇧⌘X check the highlighted row · ⇧↑ ⇧↓ check
        while moving · Esc backs out, then clears the query, then the checked rows
      </p>
    </div>
  )
}

const GLYPHS: Record<string, readonly [mac: string, other: string]> = {
  mod: ["⌘", "Ctrl"],
  meta: ["⌘", "Win"],
  cmd: ["⌘", "Win"],
  ctrl: ["⌃", "Ctrl"],
  control: ["⌃", "Ctrl"],
  alt: ["⌥", "Alt"],
  option: ["⌥", "Alt"],
  shift: ["⇧", "Shift"],
  enter: ["↵", "Enter"],
  return: ["↵", "Enter"],
  backspace: ["⌫", "Backspace"],
  delete: ["⌦", "Del"],
  esc: ["Esc", "Esc"],
  escape: ["Esc", "Esc"],
  tab: ["⇥", "Tab"],
  space: ["Space", "Space"],
  up: ["↑", "↑"],
  down: ["↓", "↓"],
  left: ["←", "←"],
  right: ["→", "→"],
  slash: ["/", "/"],
}

function isApplePlatform(): boolean {
  return typeof navigator !== "undefined" && /mac|iphone|ipad/i.test(navigator.userAgent)
}

/** Splits a react-hotkeys-hook shortcut into one label per key, with glyphs chosen for the platform. */
export function formatShortcut(shortcut: string): string[] {
  const apple = isApplePlatform()
  return shortcut
    .split("+")
    .map((part) => part.trim().toLowerCase())
    .filter(Boolean)
    .map((part) => {
      const glyph = GLYPHS[part]
      if (glyph) return apple ? glyph[0] : glyph[1]
      return part.charAt(0).toUpperCase() + part.slice(1)
    })
}

import type { PaletteItem } from "./types"

/** Adds `id` to `ids`, or removes it when present. */
export function toggleId(ids: string[], id: string): string[] {
  return ids.includes(id) ? ids.filter((existing) => existing !== id) : [...ids, id]
}

/** `ids` plus every id of `order` between `from` and `to`, inclusive, in either direction. */
export function selectRange(ids: string[], order: string[], from: string, to: string): string[] {
  const start = order.indexOf(from)
  const end = order.indexOf(to)
  if (start < 0 || end < 0) return ids
  const [low, high] = start <= end ? [start, end] : [end, start]
  const next = [...ids]
  for (const id of order.slice(low, high + 1)) {
    if (!next.includes(id)) next.push(id)
  }
  return next
}

/** The items whose ids are checked, in `items` order. Ids with no matching item are ignored. */
export function resolveTargets<T extends PaletteItem>(items: T[], ids: string[]): T[] {
  if (ids.length === 0) return []
  const checked = new Set(ids)
  return items.filter((item) => checked.has(item.id))
}

export function selectionLabel(count: number): string {
  return `${count} selected`
}

import { Kbd, KbdGroup } from "@/components/ui/kbd"

import { formatShortcut } from "./format-shortcut"

/** One keycap per key of a shortcut, e.g. ⌘ ⇧ F. */
export function ShortcutKeys({ shortcut }: { shortcut: string }) {
  return (
    <KbdGroup>
      {formatShortcut(shortcut).map((key, index) => (
        <Kbd key={`${index}-${key}`}>{key}</Kbd>
      ))}
    </KbdGroup>
  )
}

import type { ReactNode } from "react"

export type PaletteItem = { id: string; title: string }

export type PaletteAction<T extends PaletteItem> = {
  id: string
  /** End with "…" when `children` is set. */
  title: string
  run?: (item: T) => void | Promise<void>
  /** Runs once on a multi-item target. Without it, `run` is called for each item in order. */
  runMany?: (items: T[]) => void | Promise<void>
  /** Opens a sub-menu; `run` is ignored. */
  children?: PaletteAction<T>[]
  /** react-hotkeys-hook form, e.g. "mod+shift+f". */
  shortcut?: string
  /** Drawn in red and separated from the other actions. */
  destructive?: boolean
  /** Groups rows under a separator while the panel filter is empty. */
  section?: string
  /** Footer text while `run` is in flight. */
  pending?: string
  /** Toast on success; omit for none. */
  successMessage?: string
}

export type ActionPaletteProps<T extends PaletteItem> = {
  items: T[]
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  /**
   * First action is the primary (↵), second the secondary (⌘↵). `selection` is the whole
   * target: the checked items, or just `[item]` when nothing is checked.
   */
  getActions: (item: T, selection: T[]) => PaletteAction<T>[]
  getSubtitle?: (item: T) => string | undefined
  /** Right-aligned type label. */
  getMeta?: (item: T) => string | undefined
  /** Extra words matched besides the title. */
  getSearchText?: (item: T) => string
  /** Row group heading, shown while the query is empty. */
  getSection?: (item: T) => string | undefined
  /** Enables the "Create “…”" row when nothing matches. */
  onCreate?: (query: string) => void
  placeholder?: string
  footerLabel?: string
  emptyState?: { title: string; description?: string; action?: ReactNode }
  /** Checked item ids. Passing it, or `onSelectedIdsChange`, turns on the multi-item target. */
  selectedIds?: string[]
  onSelectedIdsChange?: (ids: string[]) => void
}

export type ActionPanelProps<T extends PaletteItem> = {
  item: T
  /** The whole target. With two or more, the header shows a "N selected" chip. */
  items?: T[]
  actions: PaletteAction<T>[]
  /** Sub-menu chain to open drilled into, outermost first. */
  initialPath?: PaletteAction<T>[]
  onClose: () => void
  onRun: (action: PaletteAction<T>) => void
}
